import{_ as s,l as i,o as e,c as l,v as t,p as S,x as r,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SSI","description":"","frontmatter":{"title":"SSI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssi.md","filePath":"cs/ssi.md","lastUpdated":1789023840000}'),c={name:"cs/ssi.md"};function h(I,a,E,_,A,m){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ssi" tabindex="-1">SSI <a class="header-anchor" href="#ssi" aria-label="Permalink to &quot;SSI&quot;">​</a></h1><div class="epigraph"><p>快照隔离避免脏读与大部分幻象，仍允许写偏斜。SSI 跟踪读写冲突，在形成危险结构时 abort 一侧，换近似可串行。</p><footer>—— 据 Cahill, Röhm and Fekete, Serializable Snapshot Isolation, SIGMOD 2008；Postgres SSI；Fekete 等对 SI 异常</footer></div><p><a href="/cs/occ">上一课</a>在提交点验证读集。本课站在已实现的 <a href="/cs/snapshot-isolation">快照隔离</a> 上补可串行：串行快照隔离（SSI）。主干 <a href="/cs/phantom-write-skew">写偏斜</a> 已命名异常。缺口是运行时检测，不是再举医生值班例子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SI：读自己快照，写冲突用行版本检测（第一提交者赢）。写偏斜：两事务读同一快照、写不同行，合起来违反约束。SSI：记录事务间 rw-conflict（\\(T_1\\) 读了 \\(T_2\\) 将写或已写的版本关系），若出现「危险结构」（近似两个 rw 边形成的威胁），abort 一个。缺口是<strong>假阳性</strong>：可能 abort 本可串行的事务，换简单检测。</p><p>Postgres <code>SERIALIZABLE</code> 即 SSI 实现。真正 2PL 可串行更少假阳性、更多阻塞。</p><p><span class="marginnote">Cahill, Röhm, Fekete, SIGMOD 2008。Ports and Grittner 描述 Postgres SSI。本课不把每个危险结构变体画完，只钉：SI + 冲突监视 ≈ 可串行目标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事务结束时看 in/out 冲突标志。只读事务可在有时免 abort（安全快照）。索引范围：用 SIREAD 锁一类记录「扫过的间隙」，插入者与扫者冲突——与后课间隙/谓词锁交界。</p><p>失败：<code>40001</code> 序列化失败，应用重试。这是接口，不是优化器问题。</p>',10)),(e(),S(p,null,{default:r(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SI%5B%22%E5%BF%AB%E7%85%A7%E8%AF%BB%20%2B%20%E8%A1%8C%E5%86%99%E5%86%B2%E7%AA%81%22%5D%20--%3E%20WS%5B%22%E5%86%99%E5%81%8F%E6%96%9C%E4%BB%8D%E5%8F%AF%E8%83%BD%22%5D%0A%20%20WS%20--%3E%20SSI%5B%22%E8%B7%9F%E8%B8%AA%20rw%20%E5%86%B2%E7%AA%81%22%5D%0A%20%20SSI%20--%3E%20AB%5B%22%E5%8D%B1%E9%99%A9%E5%88%99%20abort%22%5D%0A%20%20AB%20--%3E%20RET%5B%22%E5%BA%94%E7%94%A8%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 OCC：SSI 不记全读集值，而记账冲突边，内存更轻，假阳性不同。与 TSO：不必全局戳序安装，保留 SI 的读不阻塞写。长只读：后课快照；SSI 下只读仍可能被标危险，实现尽力豁免。</p><p>性能：冲突多时 abort 风暴，热点应缩小事务或改悲观。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲意向锁粒度。也不把 SSI 当分布式默认——分布式 SI 更难，Spanner 后课用真时间。谓词锁下一课族。</p><p>后课默认：要可串行优先 SSI 或 2PL，不要把 SI 叫 serializable。意向锁：多粒度锁从行走到表。</p><p>写偏斜不是幻读的同义词；SSI 两者都盯。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SSI 在 SI 上监视 rw 冲突以抑制写偏斜。</li><li>假阳性 abort，应用必须重试。</li><li>意向锁与粒度下一课。</li><li>出处：Cahill et al. SIGMOD 2008；Postgres SSI；Fekete。</li></ul>',9))])}const u=s(c,[["render",h]]);export{f as __pageData,u as default};
